# Counts numbers p * q^3 <= N with primes p < q, using a prime sieve and two pointers
def Eratosthenes(N):
    IsPrime=[True]*(N+1)

    i=2
    while i**2<=N:
        if IsPrime[i]==False:
            i+=1
            continue

        k=2
        while i*k<=N:
            IsPrime[i*k]=False
            k+=1

        i+=1

    PList=[]

    for i in range(2,N+1):
        if IsPrime[i]==True:
            PList.append(i)

    return PList

